namespace {
uint64_t quantile(const std::vector<uint64_t>& v,double p){if(v.empty())return 0; auto i=static_cast<size_t>((v.size()-1)*p+0.999999);return v[std::min(i,v.size()-1)];}
const char* source_name(ProfileSource s){switch(s){case ProfileSource::metadata:return "metadata";case ProfileSource::data:return "data";case ProfileSource::tree:return "tree";case ProfileSource::bypass:return "bypass";default:return "none";}}
std::string csv_escape(const std::string& v){std::string r="\"";for(char c:v)r+=c=='"'?"\"\"":std::string(1,c);return r+'"';}
std::string json_escape(const std::string& v){std::ostringstream o;for(unsigned char c:v){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\b':o<<"\\b";break;case '\f':o<<"\\f";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<0x20)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<unsigned(c)<<std::dec;else o<<char(c);}}return o.str();}
std::string filename_component(const std::string& value){std::string out;out.reserve(value.size());for(unsigned char c:value)out+=std::isalnum(c)||c=='-'||c=='_'||c=='.'?char(c):'_';while(out.find("..")!=std::string::npos)out.replace(out.find(".."),2,"__");return out.empty()?"unknown":out;}
bool atomic_write(const std::filesystem::path&p,const std::string&d,std::string&e){auto t=p.string()+".tmp."+std::to_string(getpid());std::ofstream o(t,std::ios::binary|std::ios::trunc);if(!o){e="open "+t;return false;}o<<d;o.flush();if(!o){e="write "+t;o.close();std::filesystem::remove(t);return false;}o.close();std::error_code ec;std::filesystem::rename(t,p,ec);if(ec){e="rename "+t+": "+ec.message();std::filesystem::remove(t);return false;}return true;}
std::string errors_string(const std::map<int,uint64_t>&e){std::ostringstream o;bool f=true;for(auto [n,c]:e){if(!f)o<<';';o<<n<<':'<<c;f=false;}return o.str();}
}
ProfilerCore::ProfilerCore(ProfilerConfig c,size_t n):config_(c),operations_(n),samples_(n){}
void ProfilerCore::record_path_locked(const std::string&p,ProfileSource src,ProfileOutcome*out,int err,MetadataTTLEvent*ttl){
 if(p.empty()) return;
 ++paths_seen_;
 auto key=std::make_pair(src,p);auto it=paths_.find(key);
 if(it==paths_.end()){if(!config_.full_paths&&paths_.size()>=config_.top_n){++paths_dropped_;++other_events_;return;}PathSnapshot x;x.source=src;x.path=p;it=paths_.emplace(key,std::move(x)).first;}
 auto&e=it->second;++e.total;if(out)++e.outcomes[static_cast<size_t>(*out)];if(ttl)++e.ttl_events[static_cast<size_t>(*ttl)];if(err)++e.errors[err];
}
void ProfilerCore::complete(size_t op,uint64_t ns,ProfileOutcome outcome,int error,const std::string&path,ProfileSource src){std::lock_guard<std::mutex>g(mutex_);if(op>=operations_.size())return;auto&o=operations_[op];++o.count;o.cumulative_ns+=ns;++o.outcomes[size_t(outcome)];++o.sources[size_t(src)];if(error)++o.errors[error];if(o.count==1){o.latency.min_ns=o.latency.max_ns=ns;}else{o.latency.min_ns=std::min(o.latency.min_ns,ns);o.latency.max_ns=std::max(o.latency.max_ns,ns);}auto&s=samples_[op];if(s.size()<config_.latency_capacity)s.push_back(ns);else if(config_.latency_capacity){std::uniform_int_distribution<uint64_t>d(0,o.count-1);auto j=d(rng_);if(j<config_.latency_capacity)s[size_t(j)]=ns;}record_path_locked(path,src,&outcome,error,nullptr);}
void ProfilerCore::record_ttl(const std::string&p,MetadataTTLEvent e){std::lock_guard<std::mutex>g(mutex_);++md_ttl_totals_[size_t(e)];record_path_locked(p,ProfileSource::metadata,nullptr,0,&e);}
ProfilerSnapshot ProfilerCore::finalize(RawSnapshot r){for(size_t i=0;i<r.snapshot.operations.size();++i){auto&o=r.snapshot.operations[i];auto&l=o.latency;l.count=o.count;l.sample_count=r.samples[i].size();l.cumulative_ns=o.cumulative_ns;std::sort(r.samples[i].begin(),r.samples[i].end());auto&s=r.samples[i];l.p50_ns=quantile(s,.5);l.p90_ns=quantile(s,.9);l.p95_ns=quantile(s,.95);l.p99_ns=quantile(s,.99);l.p999_ns=quantile(s,.999);}std::sort(r.snapshot.path_events.begin(),r.snapshot.path_events.end(),[](auto&a,auto&b){return a.total>b.total||(a.total==b.total&&std::tie(a.source,a.path)<std::tie(b.source,b.path));});return std::move(r.snapshot);}
ProfilerSnapshot ProfilerCore::snapshot()const{RawSnapshot r;{std::lock_guard<std::mutex>g(mutex_);r.snapshot.operations=operations_;r.samples=samples_;for(auto&[k,v]:paths_)r.snapshot.path_events.push_back(v);r.snapshot.paths_seen=paths_seen_;r.snapshot.paths_retained=paths_.size();r.snapshot.paths_dropped=paths_dropped_;r.snapshot.other_events=other_events_;r.snapshot.md_ttl_totals=md_ttl_totals_;}return finalize(std::move(r));}
ProfilerSnapshot ProfilerCore::snapshot_and_reset(){RawSnapshot r;{std::lock_guard<std::mutex>g(mutex_);r.snapshot.operations.swap(operations_);r.samples.swap(samples_);for(auto&[k,v]:paths_)r.snapshot.path_events.push_back(v);r.snapshot.paths_seen=paths_seen_;r.snapshot.paths_retained=paths_.size();r.snapshot.paths_dropped=paths_dropped_;r.snapshot.other_events=other_events_;r.snapshot.md_ttl_totals=md_ttl_totals_;operations_.resize(r.snapshot.operations.size());samples_.resize(r.samples.size());paths_.clear();paths_seen_=paths_dropped_=other_events_=0;md_ttl_totals_.fill(0);}return finalize(std::move(r));}
ReportResult write_snapshot_bundle_atomic(const std::filesystem::path&dir,const std::string&host,uint64_t pid,uint64_t seq,const std::string&kind,const ProfilerSnapshot&s,const ProfilerConfig&c){ReportResult r;std::error_code ec;std::filesystem::create_directories(dir,ec);if(ec){r.error=ec.message();return r;}auto stem=filename_component(host)+"-"+std::to_string(pid)+"-"+std::to_string(seq)+"-"+filename_component(kind);std::ostringstream ops;ops<<"operation,total_calls,cumulative_latency_ns,min_ns,p50_ns,p90_ns,p95_ns,p99_ns,p999_ns,max_ns,sample_count,sampling_method,cache_hits,cache_misses,negative_results,source_none,source_metadata,source_data,source_tree,source_bypass,errors\n";uint64_t calls=0,hits=0,misses=0,neg=0,ns=0;for(size_t i=0;i<s.operations.size();++i){auto&o=s.operations[i];if(!o.count)continue;calls+=o.count;hits+=o.outcomes[1];misses+=o.outcomes[2];neg+=o.outcomes[3];ns+=o.cumulative_ns;ops<<(i<size_t(OperationFunction::size)?OperationFunctionNames[i]:"unknown")<<','<<o.count<<','<<o.cumulative_ns<<','<<o.latency.min_ns<<','<<o.latency.p50_ns<<','<<o.latency.p90_ns<<','<<o.latency.p95_ns<<','<<o.latency.p99_ns<<','<<o.latency.p999_ns<<','<<o.latency.max_ns<<','<<o.latency.sample_count<<','<<o.latency.sampling_method<<','<<o.outcomes[1]<<','<<o.outcomes[2]<<','<<o.outcomes[3]<<','<<o.sources[0]<<','<<o.sources[1]<<','<<o.sources[2]<<','<<o.sources[3]<<','<<o.sources[4]<<','<<csv_escape(errors_string(o.errors))<<'\n';}
std::ostringstream paths;paths<<"source,path,total_events,success,cache_hits,cache_misses,negative_results,ttl_stores,ttl_serves,ttl_expires,ttl_clears,errors\n";for(auto&e:s.path_events)paths<<source_name(e.source)<<','<<csv_escape(e.path)<<','<<e.total<<','<<e.outcomes[0]<<','<<e.outcomes[1]<<','<<e.outcomes[2]<<','<<e.outcomes[3]<<','<<e.ttl_events[0]<<','<<e.ttl_events[1]<<','<<e.ttl_events[2]<<','<<e.ttl_events[3]<<','<<csv_escape(errors_string(e.errors))<<'\n';
std::ostringstream agg;agg<<"metric,value\n"<<"total_counted_fuse_operations,"<<calls<<'\n'<<"total_cache_hits,"<<hits<<'\n'<<"total_cache_misses,"<<misses<<'\n'<<"total_negative_results,"<<neg<<'\n'<<"cumulative_measured_latency_ns,"<<ns<<'\n'<<"paths_seen,"<<s.paths_seen<<'\n'<<"paths_retained,"<<s.paths_retained<<'\n'<<"paths_dropped,"<<s.paths_dropped<<'\n'<<"other_events,"<<s.other_events<<'\n'<<"md_enoent_ttl_stores,"<<s.md_ttl_totals[0]<<'\n'<<"md_enoent_ttl_serves,"<<s.md_ttl_totals[1]<<'\n'<<"md_enoent_ttl_expires,"<<s.md_ttl_totals[2]<<'\n'<<"md_enoent_ttl_clears,"<<s.md_ttl_totals[3]<<'\n';
auto op=dir/(stem+"-profiling_operations.csv"),pa=dir/(stem+"-profiling_top_paths.csv"),ag=dir/(stem+"-profiling_aggregate.csv");for(auto&x:std::array<std::pair<std::filesystem::path,std::string>,3>{{{op,ops.str()},{pa,paths.str()},{ag,agg.str()}}}){if(!atomic_write(x.first,x.second,r.error))return r;r.files.push_back(x.first.string());}
auto now=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();std::ostringstream m;m<<"{\n  \"schema_version\": 2,\n  \"sequence\": "<<seq<<",\n  \"kind\": \""<<json_escape(kind)<<"\",\n  \"timestamp_unix_ms\": "<<now<<",\n  \"host\": \""<<json_escape(host)<<"\",\n  \"pid\": "<<pid<<",\n  \"mode\": \""<<(c.full_paths?"full-path":c.top_n?"bounded-admitted-set":"aggregate-only")<<"\",\n  \"config\": {\"top_n\": "<<c.top_n<<", \"latency_capacity\": "<<c.latency_capacity<<", \"sampling_method\": \"reservoir_algorithm_r\"},\n  \"paths_seen\": "<<s.paths_seen<<", \"paths_retained\": "<<s.paths_retained<<", \"paths_dropped\": "<<s.paths_dropped<<", \"other_events\": "<<s.other_events<<",\n  \"files\": [\""<<json_escape(op.filename().string())<<"\", \""<<json_escape(pa.filename().string())<<"\", \""<<json_escape(ag.filename().string())<<"\"]\n}\n";auto mp=dir/(stem+"-manifest.json");if(!atomic_write(mp,m.str(),r.error))return r;r.manifest_path=mp.string();r.files.push_back(r.manifest_path);r.success=true;return r;}
